    double M_initial = 4.3e6 * 1.989e30;
    double c = 3e8;
    double r = 1.27e10;
    double spin_factor = 0.3;         // Dimensionless spin parameter
    double tau_Omega = 9e9 * 3.156e7; // Spin-down timescale (s) - 9 Gyr
    double M_dot_0 = 0.01;
    double tau_acc = 9e9 * 3.156e7;

