    double r;       // 2.838e20 m (30k ly)
    double Hz;      // 2.19e-18 s^-1 (z=0.0105)
    double B;       // 1e-5 T
    double B_crit;  // 4.4e13 T
    double SFR_factor; // 20 / 2e11 = 1e-10
    double tau_SF;  // 3.156e15 s (100 Myr)
